import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"明爻第十","description":"杭氏易學 - 明爻第十","frontmatter":{"title":"明爻第十","description":"杭氏易學 - 明爻第十"},"headers":[],"relativePath":"classics/hangshi/011.md","filePath":"classics/hangshi/011.md"}'),l={name:"classics/hangshi/011.md"};function i(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"明爻第十",tabindex:"-1"},[r("明爻第十 "),e("a",{class:"header-anchor",href:"#明爻第十","aria-label":"Permalink to “明爻第十”"},"​")],-1),e("p",null,"積爻而成卦，故爻為卦之體。爻動而卦變，故爻又為卦之用。卦之體用，具在於爻。《說卦傳》曰：“昔者聖人之作《易》也，將以順性命之理。是以立天之道曰陰與陽，立地之道曰柔與剛，立人之道曰仁與義。兼三才而兩之，故《易》六畫而成卦。分陰分陽，迭用柔剛，故《易》六位而成章。”《系傳》曰：“《易》之為書也，廣大悉備。有天道焉，有人道焉，有地道焉。兼三才而兩之，故六。六者非它也，三才之道也。道有變動故曰爻，爻有等故曰物，物相雜故曰文。文不當故吉凶生焉。”又曰：“《易》之為書也不可遠，為道也屢遷。變動不居，周流六虛。上下無常，剛柔相易。不可為典要，唯變所適。”又曰：“爻也者效此者也，象也者像此者也。爻象動乎內，吉凶見乎外，功業見乎變，聖人之情見乎辭。”孔子之所以言爻者，詳且備矣。後世言《易》者，既昧於象數，而六虛六位之義，亦泛焉而莫知所指。每卦僅就所見之上下六爻，為承應當否，卦之情其何由見哉！",-1),e("p",null,"卦氣由下生，故以下為初。重三畫之卦為六畫，仍分三才。陽奇陰偶，陽剛陰柔。以配天地，中爻為人，曰仁曰義。上下進退，為內外兩象之中樞。孔子贊《易》，《彖傳》以內外兩象之陰陽剛柔，釋一卦之義。《象傳》則專取中爻，聯合上下象數，以人合天。六十四卦《象傳》，皆曰“君子以”或“先王以”者，即以人事明天地之道者也。天地之道往復不窮，而人事之千變萬化，皆在三四兩爻之反覆。孔子曰“其初難知，其上易知，本末也”，《大過?彖》曰“本末弱也”。明六爻之本末，而後一卦之體用可知。而元亨利貞，亦可以陰陽之升降上下而明其序也。",-1),e("p",null,"端木氏曰：《易》太極含三為一，乾坤上下中，上天極，立在下地極，而中人極。離坎天地中，日月二人象，天地中人道，離坎交中，天地間生人。",-1),e("p",null,"天地顛，乾下首，生人出。乾是坎，北極艮背。坤是離，南極巽高。而中極人道，震兌出入，天地大義人之終始。此六爻三極之道也。",-1)])])}const f=s(l,[["render",i]]);export{_ as __pageData,f as default};
